40	const AttachmentThumbnails = ({ attachments }: { attachments: Attachment[] }) => {
41	  const visualAttachments = attachments.filter(
42	    (attachment) =>
43	      getAttachmentType(attachment) === "image/*" || getAttachmentType(attachment) === "video/*" || isMotionAttachment(attachment),
44	  );
45	  const items = buildAttachmentVisualItems(visualAttachments);
46	  const images = items.filter((item) => item.kind === "image" || item.kind === "motion");
47	  const others = items.filter((item) => item.kind === "video");
48	
49	  return (
50	    <div className="flex items-center gap-1.5 flex-wrap">
51	      {images.map((item) => (
52	        <div key={item.id} className="relative">
53	          <img
54	            src={item.posterUrl}
55	            alt={item.filename}
56	            className="w-10 h-10 rounded border border-border object-cover bg-muted/40"
57	            loading="lazy"
58	          />
59	          {item.kind === "motion" && (
60	            <span className="absolute left-1 top-1 rounded bg-black/70 px-1 py-0.5 text-[8px] font-semibold leading-none text-white">
61	              LIVE
62	            </span>
63	          )}
64	        </div>
65	      ))}
66	      {others.map((item) => (
