76	const PreviewMeta = ({
77	  creator,
78	  showCreator,
79	  memoName,
80	  showMemoId,
81	}: {
82	  creator?: User;
83	  showCreator?: boolean;
84	  memoName?: string;
85	  showMemoId?: boolean;
86	}) => {
87	  const creatorName = creator?.displayName || creator?.username;
88	  const memoId = showMemoId && memoName ? extractMemoIdFromName(memoName).slice(0, 6) : undefined;
89	
90	  if (!creatorName && !memoId) {
91	    return null;
92	  }
93	
94	  return (
95	    <div className="flex items-center gap-1.5 text-xs text-muted-foreground leading-none shrink-0">
96	      {showMemoId && memoId && (
97	        <span className="text-[8px] font-mono px-1 py-0.5 rounded border border-border bg-muted/40 shrink-0">{memoId}</span>
98	      )}
99	      {showCreator && creatorName && <span className="font-medium text-foreground/80 truncate">{creatorName}</span>}
100	    </div>
101	  );
102	};
