167	export function extractTasks(markdown: string): TaskItem[] {
168	  const tree = fromMarkdown(markdown, {
169	    extensions: [gfm()],
170	    mdastExtensions: [gfmFromMarkdown()],
171	  });
172	
173	  const lines = markdown.split("\n");
174	  const tasks: TaskItem[] = [];
175	  let taskIndex = 0;
176	
177	  visit(tree, "listItem", (node: ListItem) => {
178	    if (typeof node.checked === "boolean" && node.position?.start.line) {
179	      const lineNumber = node.position.start.line - 1;
180	      const line = lines[lineNumber];
181	
182	      // Extract indentation
183	      const indentMatch = line.match(/^(\s*)/);
184	      const indentation = indentMatch ? indentMatch[1].length : 0;
185	
186	      // Extract content (text after the checkbox)
187	      const contentMatch = line.match(/^\s*[-*+]\s+\[[ xX]\]\s+(.*)/);
188	      const content = contentMatch ? contentMatch[1] : "";
189	
190	      tasks.push({
191	        lineNumber,
192	        taskIndex: taskIndex++,
193	        checked: node.checked,
194	        content,
195	        indentation,
196	      });
197	    }
198	  });
199	
200	  return tasks;
201	}
