1	import type { Root, Text } from "mdast";
2	import type { Node as UnistNode } from "unist";
3	import { visit } from "unist-util-visit";
4	import type { MentionNode, MentionNodeData } from "@/types/markdown";
5	import { isMentionChar, MAX_MENTION_LENGTH } from "@/utils/mention-grammar";
6	
7	function isMentionBoundary(char: string): boolean {
8	  if (!char) return true;
9	  return !isMentionChar(char);
10	}
11	
12	type Segment = { type: "text"; value: string } | { type: "mention"; value: string };
13	
14	export function parseMentionsFromText(text: string): Segment[] {
15	  const segments: Segment[] = [];
16	  const chars = [...text];
17	  let i = 0;
18	
19	  while (i < chars.length) {
20	    const prevChar = i > 0 ? chars[i - 1] : "";
21	    if (chars[i] === "@" && isMentionBoundary(prevChar) && i + 1 < chars.length && isMentionChar(chars[i + 1])) {
22	      let j = i + 1;
23	      while (j < chars.length && isMentionChar(chars[j]) && j - i - 1 < MAX_MENTION_LENGTH) {
24	        j++;
25	      }
26	
27	      const username = chars.slice(i + 1, j).join("");
28	      const hasLetterOrNumber = [...username].some((char) => /[A-Za-z0-9]/.test(char));
29	      if (username && hasLetterOrNumber) {
30	        segments.push({ type: "mention", value: username.toLowerCase() });
31	        i = j;
32	        continue;
33	      }
34	    }
35	
36	    let j = i + 1;
37	    while (j < chars.length && chars[j] !== "@") {
38	      j++;
39	    }
40	    segments.push({ type: "text", value: chars.slice(i, j).join("") });
41	    i = j;
42	  }
43	
44	  return segments;
45	}
46	
47	export function extractMentionUsernames(text: string): string[] {
48	  const usernames = parseMentionsFromText(text)
49	    .filter((segment): segment is { type: "mention"; value: string } => segment.type === "mention")
50	    .map((segment) => segment.value);
51	  return Array.from(new Set(usernames));
52	}
53	
54	function createMentionNode(username: string): MentionNode {
55	  const data: MentionNodeData = {
56	    hName: "span",
57	    hProperties: {
58	      className: "mention",
59	      "data-mention": username,
60	    },
61	    hChildren: [{ type: "text", value: `@${username}` }],
62	  };
63	
64	  return {
65	    type: "mentionNode",
66	    value: username,
67	    data,
68	  } as MentionNode;
69	}
70	
71	export const remarkMention = () => {
72	  return (tree: Root) => {
73	    visit(tree, (node, index, parent) => {
74	      if (node.type !== "text" || !parent || index === null) return;
75	
76	      const textNode = node as Text;
77	      const segments = parseMentionsFromText(textNode.value);
78	      if (segments.every((segment) => segment.type === "text")) {
79	        return;
80	      }
81	
82	      const newNodes = segments.map((segment) => {
83	        if (segment.type === "mention") {
84	          return createMentionNode(segment.value);
85	        }
86	        return {
87	          type: "text",
88	          value: segment.value,
89	        } as Text;
90	      });
91	
92	      if (typeof index === "number") {
93	        (parent.children as UnistNode[]).splice(index, 1, ...(newNodes as UnistNode[]));
94	      }
95	    });
96	  };
97	};
