2	import dayjs from "dayjs";
3	import { countBy } from "lodash-es";
4	import { useMemo } from "react";
5	import type { MemoExplorerContext } from "@/components/MemoExplorer";
6	import { type MemoTimeBasis, useView } from "@/contexts/ViewContext";
7	import useCurrentUser from "@/hooks/useCurrentUser";
8	import { useAllUserStats, useUserStats } from "@/hooks/useUserQueries";
9	import { State } from "@/types/proto/api/v1/common_pb";
10	import type { UserStats } from "@/types/proto/api/v1/user_service_pb";
11	import type { StatisticsData } from "@/types/statistics";
12	
13	export interface FilteredMemoStats {
14	  statistics: StatisticsData;
15	  tags: Record<string, number>;
16	  loading: boolean;
17	}
18	
19	export interface UseFilteredMemoStatsOptions {
20	  userName?: string;
21	  context?: MemoExplorerContext;
22	}
23	
24	const toDateString = (date: Date) => dayjs(date).format("YYYY-MM-DD");
25	
26	const timestampsForBasis = (stats: UserStats, basis: MemoTimeBasis) => {
27	  const createdArray = stats.memoCreatedTimestamps ?? [];
28	  const updatedArray = stats.memoUpdatedTimestamps ?? [];
29	  const wantUpdated = basis === "update_time";
30	  const oldServerFallback = wantUpdated && updatedArray.length === 0 && createdArray.length > 0;
31	  if (oldServerFallback) {
32	    console.warn("UserStats.memo_updated_timestamps not present; falling back to memo_created_timestamps");
33	  }
34	  return wantUpdated && !oldServerFallback ? updatedArray : createdArray;
35	};
36	
37	export const useFilteredMemoStats = (options: UseFilteredMemoStatsOptions = {}): FilteredMemoStats => {
38	  const { userName, context } = options;
39	  const currentUser = useCurrentUser();
40	  const { timeBasis } = useView();
41	
42	  // home/profile: use backend per-user stats (full tag set, not page-limited)
43	  const { data: userStats, isLoading: isLoadingUserStats } = useUserStats(userName);
44	  // explore/archived: fetch backend grouped stats and aggregate them locally.
45	  // ListAllUserStats AND's the request filter with the server's auth filter, so
46	  // private memos are not included unless explicitly visible to the current user.
47	  const exploreVisibilityFilter = currentUser != null ? 'visibility in ["PUBLIC", "PROTECTED"]' : 'visibility in ["PUBLIC"]';
48	  const allUserStatsRequest =
49	    context === "explore"
50	      ? { state: State.NORMAL, filter: exploreVisibilityFilter }
51	      : context === "archived"
52	        ? { state: State.ARCHIVED }
53	        : {};
54	  const shouldFetchAllUserStats = context === "explore" || (context === "archived" && !!currentUser?.name);
55	  const { data: allUserStats = [], isLoading: isLoadingAllUserStats } = useAllUserStats(allUserStatsRequest, {
56	    enabled: shouldFetchAllUserStats,
57	  });
58	
59	  const data = useMemo(() => {
60	    const loading = isLoadingUserStats || isLoadingAllUserStats;
61	    let activityStats: Record<string, number> = {};
62	    let tagCount: Record<string, number> = {};
63	
64	    if (context === "explore" || context === "archived") {
65	      const displayDates: string[] = [];
66	      for (const stats of allUserStats) {
67	        for (const [tag, count] of Object.entries(stats.tagCount ?? {})) {
68	          tagCount[tag] = (tagCount[tag] ?? 0) + count;
69	        }
70	        displayDates.push(
71	          ...timestampsForBasis(stats, timeBasis)
72	            .map((ts) => (ts ? timestampDate(ts) : undefined))
73	            .filter((date): date is Date => date !== undefined)
74	            .map(toDateString),
75	        );
76	      }
77	      activityStats = countBy(displayDates);
78	    } else if (userName && userStats) {
79	      // home/profile: use backend per-user stats.
80	      const sourceArray = timestampsForBasis(userStats, timeBasis);
81	      if (sourceArray.length > 0) {
82	        activityStats = countBy(
83	          sourceArray
84	            .map((ts) => (ts ? timestampDate(ts) : undefined))
85	            .filter((date): date is Date => date !== undefined)
86	            .map(toDateString),
87	        );
88	      }
89	      if (userStats.tagCount) {
90	        tagCount = userStats.tagCount;
91	      }
92	    }
93	
94	    return { statistics: { activityStats, timeBasis }, tags: tagCount, loading };
95	  }, [context, userName, userStats, allUserStats, isLoadingUserStats, isLoadingAllUserStats, timeBasis]);
96	
97	  return data;
98	};
