3	import { cn } from "@/lib/utils";
4	import { useTranslate } from "@/utils/i18n";
5	
6	// A collapsed section shows this much content; anything taller folds behind a fade.
7	export const CLAMP_PREVIEW_HEIGHT_PX = 360;
8	// Only fold when content is taller than this, so cards barely over the preview aren't
9	// clamped for the sake of a few hidden pixels.
10	export const CLAMP_TRIGGER_HEIGHT_PX = 420;
11	
12	interface ClampedSectionProps {
13	  /** When false, children render untouched with no measurement. */
14	  enabled: boolean;
15	  children: ReactNode;
16	}
17	
18	/**
19	 * The one truncation mechanism for compact cards: measure the content, and when it is
20	 * tall enough, collapse it to a fixed-height preview with a fade and a Show more/less
21	 * toggle. The inner div is never clamped, so observing it keeps the measurement live
22	 * while images and embeds load.
23	 */
24	const ClampedSection = ({ enabled, children }: ClampedSectionProps) => {
25	  const t = useTranslate();
26	  const measureRef = useRef<HTMLDivElement>(null);
27	  const [clamped, setClamped] = useState(false);
28	  const [expanded, setExpanded] = useState(false);
29	
30	  useEffect(() => {
31	    const el = measureRef.current;
32	    if (!enabled || !el) {
33	      setClamped(false);
34	      return;
35	    }
36	    const check = () => setClamped(el.offsetHeight > CLAMP_TRIGGER_HEIGHT_PX);
37	    check();
38	    if (typeof ResizeObserver === "undefined") return;
39	    const observer = new ResizeObserver(check);
40	    observer.observe(el);
41	    return () => observer.disconnect();
42	  }, [enabled]);
43	
44	  const collapsed = clamped && !expanded;
45	
46	  return (
47	    <>
48	      <div
49	        className={cn("relative w-full", collapsed && "overflow-hidden")}
50	        style={collapsed ? { maxHeight: CLAMP_PREVIEW_HEIGHT_PX } : undefined}
51	      >
52	        <div ref={measureRef} className="w-full flex flex-col justify-start items-start gap-2">
53	          {children}
54	        </div>
55	        {collapsed && (
56	          <div className="pointer-events-none absolute inset-x-0 bottom-0 h-12 bg-linear-to-t from-card from-0% via-card/60 via-40% to-transparent to-100%" />
57	        )}
58	      </div>
59	      {clamped && (
60	        <button
61	          type="button"
62	          className="inline-flex items-center gap-1 px-2 py-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
63	          onClick={() => setExpanded((prev) => !prev)}
64	        >
65	          <span>{t(collapsed ? "memo.show-more" : "memo.show-less")}</span>
66	          {collapsed ? <ChevronDown className="w-3 h-3" /> : <ChevronUp className="w-3 h-3" />}
67	        </button>
68	      )}
69	    </>
70	  );
71	};
72	
73	export default ClampedSection;
