1	import { cn } from "@/lib/utils";
2	import type { AttachmentVisualItem } from "@/utils/media-item";
3	
4	export type VisualGalleryCell = {
5	  item: AttachmentVisualItem;
6	  className?: string;
7	  overlayLabel?: string;
8	};
9	
10	/** Resolved layout for attachment visual previews — keeps grid rules in one place. */
11	export type VisualGalleryLayout =
12	  | { mode: "single"; item: AttachmentVisualItem }
13	  | { mode: "collage"; containerClassName: string; cells: VisualGalleryCell[] };
14	
15	const TWO_ITEM_GRID_HEIGHT_CLASS = "h-[11rem] sm:h-[13rem] md:h-[15rem]";
16	const MOSAIC_GRID_HEIGHT_CLASS = "h-[13rem] sm:h-[16rem] md:h-[18rem]";
17	/** 2 rows × 3 columns */
18	const SIX_UP_GRID_HEIGHT_CLASS = "h-[14rem] sm:h-[17rem] md:h-[20rem]";
19	
20	/** Max thumbnails shown in the 2×3 collage before `+N` on the last cell. */
21	export const COLLAGE_MAX_VISIBLE_CELLS = 6;
22	
23	/**
24	 * Maps N visual items to a gallery layout (single, 2-up, 3-mosaic, 2×2, or 2×3 with optional +N).
25	 */
26	export const resolveVisualGalleryLayout = (items: AttachmentVisualItem[]): VisualGalleryLayout | null => {
27	  const count = items.length;
28	
29	  if (count === 0) {
30	    return null;
31	  }
32	
33	  if (count === 1) {
34	    return { mode: "single", item: items[0] };
35	  }
36	
37	  if (count === 2) {
38	    return {
39	      mode: "collage",
40	      containerClassName: cn("grid grid-cols-2 gap-2", TWO_ITEM_GRID_HEIGHT_CLASS),
41	      cells: items.map((item) => ({ item })),
42	    };
43	  }
44	
45	  if (count === 3) {
46	    return {
47	      mode: "collage",
48	      containerClassName: cn("grid grid-cols-2 grid-rows-2 gap-2", MOSAIC_GRID_HEIGHT_CLASS),
49	      cells: [{ item: items[0], className: "row-span-2" }, { item: items[1] }, { item: items[2] }],
50	    };
51	  }
52	
53	  if (count === 4) {
54	    return {
55	      mode: "collage",
56	      containerClassName: cn("grid grid-cols-2 grid-rows-2 gap-2", MOSAIC_GRID_HEIGHT_CLASS),
57	      cells: items.map((item) => ({ item })),
58	    };
59	  }
60	
61	  const visible = items.slice(0, COLLAGE_MAX_VISIBLE_CELLS);
62	  const overflowCount = items.length - visible.length;
63	
64	  return {
65	    mode: "collage",
66	    containerClassName: cn("grid grid-cols-3 grid-rows-2 gap-2", SIX_UP_GRID_HEIGHT_CLASS),
67	    cells: visible.map((item, index) => ({
68	      item,
69	      overlayLabel: index === visible.length - 1 && overflowCount > 0 ? `+${overflowCount}` : undefined,
70	    })),
71	  };
72	};
